import re, glob
edges=set()
nodes=set()
for i in range(1,13):
    fn=f"chunk-{i:02d}.txt"
    for line in open(fn):
        m=re.search(r'component (C\d+) depends on (C\d+)', line)
        if m:
            a,b=m.group(1),m.group(2)
            edges.add((a,b))
            nodes.add(a); nodes.add(b)

# Tarjan SCC
import sys
sys.setrecursionlimit(10000)
graph={n:[] for n in nodes}
for a,b in edges:
    graph[a].append(b)

index_counter=[0]
stack=[]
lowlink={}
index={}
on_stack={}
result=[]

def strongconnect(node):
    index[node]=index_counter[0]
    lowlink[node]=index_counter[0]
    index_counter[0]+=1
    stack.append(node)
    on_stack[node]=True
    for successor in graph[node]:
        if successor not in index:
            strongconnect(successor)
            lowlink[node]=min(lowlink[node],lowlink[successor])
        elif on_stack.get(successor):
            lowlink[node]=min(lowlink[node],index[successor])
    if lowlink[node]==index[node]:
        comp=[]
        while True:
            w=stack.pop()
            on_stack[w]=False
            comp.append(w)
            if w==node:
                break
        result.append(comp)

for n in nodes:
    if n not in index:
        strongconnect(n)

sccs = [c for c in result if len(c)>1]
print("Total nodes:", len(nodes))
print("Num SCCs with >1 node:", len(sccs))
for c in sccs:
    print(sorted(c, key=lambda x:int(x[1:])))
