            edges.add((a,b))
            nodes.add(a); nodes.add(b)

graph={n:[] for n in nodes}
for a,b in edges:
    graph[a].append(b)

import sys
sys.setrecursionlimit(10000)
index_counter=[0]; stack=[]; lowlink={}; index={}; on_stack={}; result=[]
def strongconnect(node):
    index[node]=index_counter[0]; lowlink[node]=index_counter[0]; index_counter[0]+=1
    stack.append(node); on_stack[node]=True
    for succ in graph[node]:
        if succ not in index:
            strongconnect(succ)
            lowlink[node]=min(lowlink[node],lowlink[succ])
        elif on_stack.get(succ):
            lowlink[node]=min(lowlink[node],index[succ])
    if lowlink[node]==index[node]:
        comp=[]
        while True:
            w=stack.pop(); on_stack[w]=False; comp.append(w)
            if w==node: break
        result.append(comp)

for n in nodes:
    if n not in index:
        strongconnect(n)

sccs=[c for c in result if len(c)>1]
print("nodes", sorted(nodes, key=lambda x:int(x[1:])))
print("num multi-node SCCs", len(sccs))
for c in sccs:
    print(sorted(c, key=lambda x:int(x[1:])))
